def check(x):
    expression = (8*x - 41) * (x + 3)**2
    # Check if expression is a perfect cube
    if expression < 0:
        cbrt = round(expression**(1/3))
        return cbrt**3 == expression
    else:
        cbrt = round(expression**(1/3))
        return cbrt**3 == expression

solutions = []
for x in [-3, 5]:
    if check(x):
        solutions.append(x)

print(solutions)
